SELECT 
FROM TBL_FUND_POOLS
WHERE POOLCODE = #{poolCode} AND ORGID = #{orgId}

SELECT 
FROM TBL_FUND_POOLS
WHERE ORGID = #{orgId}

    AND POOLCODE LIKE CONCAT('%', #{poolCode}, '%')


    AND POOLNAME LIKE CONCAT('%', #{poolName}, '%')


    AND POOLTYPE = #{poolType}


    AND POOLSTATUS = #{poolStatus}


    AND CURRENCYCODE = #{currencyCode}

ORDER BY CREATETIME DESC

SELECT COALESCE(SUM(TOTALBALANCE), 0)
FROM TBL_FUND_POOLS
WHERE ORGID = #{orgId}

SELECT COALESCE(SUM(AVAILABLEBALANCE), 0)
FROM TBL_FUND_POOLS
WHERE ORGID = #{orgId}

SELECT COALESCE(SUM(RESERVEBALANCE), 0)
FROM TBL_FUND_POOLS
WHERE ORGID = #{orgId}

mapper.update:
UPDATE TBL_FUND_POOLS
SET TOTALBALANCE = TOTALBALANCE - #{amount},
    AVAILABLEBALANCE = AVAILABLEBALANCE - #{amount},
    UPDATETIME = CURRENT_TIMESTAMP
WHERE POOLID = #{poolId}
AND AVAILABLEBALANCE >= #{amount}

mapper.select:
WITH RECURSIVE pool_hierarchy AS ( SELECT POOLID, POOLCODE, POOLNAME, MASTERPOOLID, 0 AS level FROM TBL_FUND_POOLS WHERE MASTERPOOLID IS NULL AND ORGID = #{orgId}
UNION ALL
SELECT p.POOLID, p.POOLCODE, p.POOLNAME, p.MASTERPOOLID, ph.level + 1 FROM TBL_FUND_POOLS p INNER JOIN pool_hierarchy ph ON p.MASTERPOOLID = ph.POOLID WHERE p.ORGID = #{orgId} ) SELECT * FROM pool_hierarchy ORDER BY level, POOLCODE

mapper.delete:
DELETE FROM TBL_FUND_POOLS
WHERE POOLSTATUS = 'CLOSED'
AND ORGID = #{orgId}
AND UPDATETIME < #{beforeDate}
AND TOTALBALANCE = 0

