INSERT INTO TBL_FUND_POOL_OPERATION_LOGS (
    POOLID, OPERATION, OPERATIONDATA, OPERATORID, OPERATIONTIME
) VALUES (
    #{poolId}, #{operation}, #{operationData}, #{operatorId}, CURRENT_TIMESTAMP
