mapper.select:
SELECT LOGID, POOLID, OPERATION, OPERATIONDATA, OPERATORID, OPERATIONTIME FROM TBL_FUND_POOL_OPERATION_LOGS WHERE POOLID = #{poolId}
AND DATE(OPERATIONTIME) >= #{startDate}
AND DATE(OPERATIONTIME) <= #{endDate}
ORDER BY OPERATIONTIME DESC
